class Validator:
    def __init__(self, data):
        self.data = data
    def validate_age(self):
        return int(self.data.get('age', 0))

def validate_email(self):
    email = self.data.get('email', '')
    if '@' not in email or '.' not in email:
        self.errors['email'] = 'Invalid email format'
        return False
    return True

